<?php ?><section class="card"><h2>Account controls</h2><p class="hint">Deactivation immediately prevents sign-in. Permanent deletion removes the account and personal records. Raw device logs remain unlinked.</p><div class="actions" style="margin-top:20px"><?php if(can($pdo,$user,'employees.edit')):?><form method="post" data-confirm="Change login access for this employee?"><?php ftoken();?><input type="hidden" name="action" value="toggle_employee"><input type="hidden" name="id" value="<?=$id?>"><button class="button"><?=$employee['active']?'Deactivate':'Activate'?> login</button></form><?php endif;if($user['role']==='super_admin'):?><form method="post" data-confirm="Permanently delete this employee, login, attendance, requests, documents and mappings? This cannot be undone. Raw device logs remain unlinked."><?php ftoken();?><input type="hidden" name="action" value="delete_employee"><input type="hidden" name="delete_mode" value="permanent"><input type="hidden" name="id" value="<?=$id?>"><button class="button danger">Permanently delete employee</button></form><?php endif;?></div></section><?php if($user['role']==='super_admin'):?><section class="card"><h2>Reset employee password</h2><p class="hint">Use this when an employee cannot access their account. A password change is required at next sign-in and existing sessions are revoked.</p><form method="post" data-confirm="Reset this employee's password and sign out their existing sessions?"><?php ftoken();?><input type="hidden" name="action" value="reset_employee_password"><input type="hidden" name="id" value="<?=$id?>"><label>Temporary password<input type="password" name="temporary_password" minlength="12" maxlength="72" autocomplete="new-password"><span class="hint">Leave blank for User@123.</span></label><div class="form-actions"><button class="button">Reset password</button></div></form></section><?php endif;?>
